/* Registration recovery and refund bookkeeping. No bank transfer is performed. */
(function(root){'use strict';const R=root.Reunion;
function prepare(s){s.refunds??=[];s.refundLinks??=[];for(const x of s.refunds){if(x.status==='予定')x.status='planned';if(x.status==='模擬完了')x.status='recorded';x.refundDate??=(x.at||'').slice(0,10);x.reference??='';}return s;}
function staff(s,uid){const u=s.people.find(p=>p.id===Number(uid));if(!u||!['owner','organizer'].includes(u.role))throw new Error('幹事のログインが必要です。');return u;}
function person(s,id){const p=s.people.find(p=>p.id===Number(id));if(!p)throw new Error('申込がありません。');return p;}
function why(v){v=String(v||'').trim();if(!v||v.length>1000)throw new Error('処理理由を1〜1000文字で入力してください。');return v;}
function positive(n){if(!Number.isSafeInteger(n)||n<1||n>100000000)throw new Error('金額は1〜100,000,000円の整数です。');}
function billed(p){return ['cancelled','rejoin_requested'].includes(p.status)?0:p.amount;}
function refunded(s,id){prepare(s);return s.refunds.filter(x=>x.personId===Number(id)&&x.status==='recorded').reduce((n,x)=>n+x.amount,0);}
function planned(s,id){prepare(s);return s.refunds.filter(x=>x.personId===Number(id)&&x.status==='planned').reduce((n,x)=>n+x.amount,0);}
function netPaid(s,id){return R.totalPaid(s,Number(id))-refunded(s,id);}
function available(s,id){const p=person(s,id);return Math.max(0,netPaid(s,id)-billed(p)-planned(s,id));}
function room(s){if(s.people.filter(R.active).length>=s.settings.capacity)throw new Error('参加定員に達しています。幹事へご相談ください。');}
function own(s,id,uid,revision){const p=person(s,id);if(p.id!==Number(uid))throw new Error('本人の申込だけ操作できます。');if(p.revision!==Number(revision))throw new Error('内容が更新されています。画面を読み直してください。');return p;}
function status(s,p,next,uid,action,reason){const before={status:p.status,revision:p.revision};p.status=next;p.revision=(p.revision||0)+1;R.audit(s,person(s,uid).name,action,p.number,before,{status:next,revision:p.revision},reason);return p;}
function withdraw(s,id,revision,reason,uid){reason=why(reason);R.checkDeadline(s,'change');const p=own(s,id,uid,revision);if(p.status!=='cancel_requested')throw new Error('欠席申請中の申込ではありません。');room(s);return status(s,p,'active',uid,'欠席申請の取り消し',reason);}
function requestRejoin(s,id,revision,reason,uid){reason=why(reason);R.checkDeadline(s,'change');const p=own(s,id,uid,revision);if(p.status!=='cancelled')throw new Error('取消確定済みの申込ではありません。');return status(s,p,'rejoin_requested',uid,'再参加の希望',reason);}
function decideRejoin(s,id,decision,reason,uid){prepare(s);staff(s,uid);reason=why(reason);const p=person(s,id);if(p.status!=='rejoin_requested'||!['approve','reject'].includes(decision))throw new Error('再参加申請と判断を確認してください。');if(decision==='approve'){room(s);if(planned(s,id)>0)throw new Error('先に未送金の返金予定を取り消してください。');}return status(s,p,decision==='approve'?'active':'cancelled',uid,'再参加の判断',reason);}
function decideCancel(s,id,decision,reason,uid){staff(s,uid);reason=why(reason);const p=person(s,id);if(p.status!=='cancel_requested'||!['approve','reject'].includes(decision))throw new Error('欠席申請と判断を確認してください。');if(decision==='reject')room(s);return status(s,p,decision==='approve'?'cancelled':'active',uid,'欠席申請の判断',reason);}
function planRefund(s,id,n,reason,key,uid){prepare(s);staff(s,uid);reason=why(reason);const old=s.refunds.find(x=>x.requestKey===key&&key);if(old)return old;if(!/^[a-zA-Z0-9-]{16,64}$/.test(key||''))throw new Error('返金画面を読み直してください。');const p=person(s,id);if(!['active','cancelled'].includes(p.status))throw new Error('欠席・再参加の判断後に返金を登録してください。');positive(n);if(n>available(s,id))throw new Error('返金可能額を超えています。重複予定も確認してください。');const x={id:Math.max(0,...s.refunds.map(x=>x.id))+1,personId:p.id,amount:n,status:'planned',reason,requestKey:key,at:new Date().toISOString(),refundDate:'',reference:''};s.refunds.push(x);R.audit(s,person(s,uid).name,'返金予定の登録',p.number,null,x,reason);return x;}
function refund(s,id){prepare(s);const x=s.refunds.find(x=>x.id===Number(id));if(!x)throw new Error('返金記録がありません。');return x;}
function refundPaid(s,id){prepare(s);return s.refundLinks.filter(x=>x.refundId===Number(id)&&x.active).reduce((n,x)=>n+x.amount,0);}
function recordRefund(s,id,date,reference,reason,uid){staff(s,uid);reason=why(reason);const x=refund(s,id),p=person(s,x.personId);if(x.status!=='planned'||!['active','cancelled'].includes(p.status))throw new Error('申請状態と未送金の返金予定を確認してください。');date=R.parseDate(String(date));if(date>s.settings.clock)throw new Error('返金日は判定日以前にしてください。');reference=String(reference||'').trim();if(!reference||reference.length>200)throw new Error('銀行での送金確認番号などを200文字以内で入力してください。');if(refunded(s,p.id)+planned(s,p.id)>Math.max(0,R.totalPaid(s,p.id)-billed(p)))throw new Error('返金可能額を再確認してください。');const before=R.clone(x);x.status='recorded';x.refundDate=date;x.reference=reference;R.audit(s,person(s,uid).name,'返金実施の記録（送金なし）',p.number,before,x,reason);}
function cancelRefund(s,id,reason,uid){staff(s,uid);reason=why(reason);const x=refund(s,id);if(x.status!=='planned')throw new Error('未送金の返金予定だけ取り消せます。');const before=R.clone(x);x.status='cancelled';R.audit(s,person(s,uid).name,'返金予定の取り消し',person(s,x.personId).number,before,x,reason);}
function undoRefund(s,id,reason,uid){staff(s,uid);reason=why(reason);const x=refund(s,id);if(x.status!=='recorded'||refundPaid(s,id)>0)throw new Error('先に銀行出金との照合を取り消してください。');const before=R.clone(x);x.status='planned';x.refundDate='';x.reference='';R.audit(s,person(s,uid).name,'返金記録の訂正（実送金の取消ではありません）',person(s,x.personId).number,before,x,reason);}
function debitUsed(s,id){prepare(s);return (s.expenseLinks||[]).filter(x=>x.active&&x.transactionId===Number(id)).reduce((n,x)=>n+x.amount,0)+s.refundLinks.filter(x=>x.active&&x.transactionId===Number(id)).reduce((n,x)=>n+x.amount,0);}
function linkRefund(s,id,tid,n,reason,uid){staff(s,uid);reason=why(reason);positive(n);const x=refund(s,id),t=s.transactions.find(t=>t.id===Number(tid));if(x.status!=='recorded'||!t||t.state!=='confirmed'||!t.debit)throw new Error('返金記録済みの予定と確認済み銀行出金を選んでください。');if(n>x.amount-refundPaid(s,id)||n>t.debit-debitUsed(s,tid))throw new Error('返金または出金の未照合額を超えています。');const a={id:Math.max(0,...s.refundLinks.map(a=>a.id))+1,refundId:x.id,transactionId:t.id,amount:n,active:true,reason,actorId:Number(uid)};s.refundLinks.push(a);R.audit(s,person(s,uid).name,'返金と銀行出金の照合',person(s,x.personId).number,null,a,reason);return a;}
function unlinkRefund(s,id,reason,uid){prepare(s);staff(s,uid);reason=why(reason);const a=s.refundLinks.find(a=>a.id===Number(id));if(!a||!a.active)throw new Error('有効な返金照合ではありません。');a.active=false;R.audit(s,person(s,uid).name,'返金出金照合の取り消し',person(s,refund(s,a.refundId).personId).number,{active:true},a,reason);}
root.Lifecycle={prepare,billed,refunded,planned,netPaid,available,withdraw,requestRejoin,decideRejoin,decideCancel,planRefund,refundPaid,recordRefund,cancelRefund,undoRefund,debitUsed,linkRefund,unlinkRefund};if(typeof module!=='undefined')module.exports=root.Lifecycle;
})(typeof globalThis!=='undefined'?globalThis:this);
